def normalize_tags(tags):
    seen = set()
    result = []
    for tag in tags:
        key = tag.strip().casefold()
        if key not in seen:
            seen.add(key)
            result.append(tag)
    return tuple(result) if result else None

def most_common_word(words):
    counts = {}
    for word in words:
        counts[word] = counts.get(word, 0) + 1

    if not counts:
        return None

    return max(counts, key=counts.get)

def intersection_labels(first, second):
    if not first or not second:
        return None

    second_labels = set(second)
    seen = set()
    result = []

    for label in first:
        if label in second_labels and label not in seen:
            result.append(label)
            seen.add(label)

    return tuple(result)

def common_suffix(words):
    if not words:
        return None

    reversed_words = [word[::-1] for word in words]
    suffix_length = 0

    for chars in zip(*reversed_words):
        if len(set(chars)) != 1:
            break
        suffix_length += 1

    return words[0][-suffix_length:] if suffix_length else ""

def parse_clock(text):
    import re

    match = re.fullmatch(r"\s*([0-9]{1,2}):([0-9]{2})\s*(AM|PM)\s*", text, re.IGNORECASE)
    if match is None:
        raise ValueError("Invalid clock value")

    hour = int(match.group(1))
    minute = int(match.group(2))
    marker = match.group(3).upper()

    if not 1 <= hour <= 12 or not 0 <= minute <= 59:
        raise ValueError("Invalid clock value")

    return (hour % 12) * 60 + minute + (720 if marker == "PM" else 0)

def sort_events(events):
    if not events:
        return None

    from datetime import datetime

    return tuple(sorted(events, key=lambda event: datetime.fromisoformat(event["time"])))

def matrix_multiply(left, right):
    if not left or not right:
        return None

    left_columns = len(left[0])
    right_columns = len(right[0])

    if any(len(row) != left_columns for row in left):
        raise ValueError("left matrix must be rectangular")
    if any(len(row) != right_columns for row in right):
        raise ValueError("right matrix must be rectangular")
    if left_columns != len(right):
        raise ValueError("matrix dimensions are incompatible")

    return tuple(
        tuple(
            sum(left[i][k] * right[k][j] for k in range(left_columns))
            for j in range(right_columns)
        )
        for i in range(len(left))
    )

def count_islands(grid):
    if not grid:
        return None

    columns = len(grid[0])
    if any(len(row) != columns for row in grid):
        raise ValueError("grid must be rectangular")

    if any(cell not in (0, 1) for row in grid for cell in row):
        raise ValueError("grid cells must be 0 or 1")

    rows = len(grid)
    visited = [[False] * columns for _ in range(rows)]
    islands = 0

    for row in range(rows):
        for column in range(columns):
            if grid[row][column] != 1 or visited[row][column]:
                continue

            islands += 1
            visited[row][column] = True
            stack = [(row, column)]

            while stack:
                current_row, current_column = stack.pop()

                for next_row, next_column in (
                    (current_row - 1, current_column),
                    (current_row + 1, current_column),
                    (current_row, current_column - 1),
                    (current_row, current_column + 1),
                ):
                    if (
                        0 <= next_row < rows
                        and 0 <= next_column < columns
                        and not visited[next_row][next_column]
                        and grid[next_row][next_column] == 1
                    ):
                        visited[next_row][next_column] = True
                        stack.append((next_row, next_column))

    return islands
